import {Component, h, Host, Prop} from "@stencil/core";

/**
 * @data-testid hbr-table-header-sorting-button - The sortable header label button rendered for sortable columns.
 */

@Component({
  tag: "hbr-table-header-cell",
  styleUrl: "style.scss"
})
export class TableHeaderCell {
  @Prop() data: any = {};
  ref: HTMLElement;
  host: HTMLElement;

  componentDidRender() {
    if (this.ref) {
      const slotList = Array.from(this.ref.querySelectorAll("[slot]"));
      slotList.forEach(ele => {
        const slotContainer = this.ref.querySelector(`[data-slot="${ele.getAttribute("slot")}"]`);
        if (slotContainer && !slotContainer.contains(ele)) {
          slotContainer.appendChild(ele);
        }
      });
    }
  }

  render() {
    const name = this.data?.noName ? null : this.data?.name;
    return (
      <Host
        ref={ref => {
          this.ref = ref;
        }}
      >
        <div class="hbr-table-header-cell-top" data-header-sort="true">
          <div class="hbr-table-header-cell-top-slot" data-slot="top">
            <slot name="top">
              <div class="header-content">
                <div class="hbr-table-header-cell-top-prefix" data-slot="prefix">
                  <slot name="prefix"></slot>
                </div>
                <div class="hbr-table-header-cell-name" data-slot="name">
                  <slot name="name">
                    {this.data?.sortable ? (
                      <div
                        role="button"
                        tabindex="0"
                        data-header-sort="true"
                        data-testid="hbr-table-header-sorting-button"
                        class="hbr-header-cell-sorting-button"
                        title={name}
                        onKeyDown={e => {
                          if ([" ", "Enter"].includes(e.key)) {
                            const ele = e.target as HTMLElement;
                            ele?.click();
                          }
                        }}
                      >
                        {name}
                      </div>
                    ) : (
                      <div>{name}</div>
                    )}
                  </slot>
                </div>

                <div class="hbr-table-header-cell-top-suffix" data-slot="suffix">
                  <slot name="suffix"></slot>
                </div>
                <div class="hbr-table-header-cell-top-end" data-slot="top-end">
                  <slot name="top-end"></slot>
                </div>
              </div>
            </slot>
          </div>
        </div>
        <div class="hbr-table-header-cell-bottom" data-slot="bottom">
          <slot name="bottom"></slot>
        </div>
      </Host>
    );
  }
}
